"""EXP-CAREE-001 Experience careers OpenAPI contract extension."""
def extend_experience(spec):
    from authorization import object_schema, operation, parameter, UUID, VERSION, REF
    models=spec['components']['schemas']; paths=spec['paths']
    base_field={'key':{'type':'string','pattern':'^[a-z][a-zA-Z0-9_]{0,79}$'},'type':{'enum':['TEXT','LONG_TEXT','SELECT','BOOLEAN']},'required':{'type':'boolean'},'maximumLength':{'type':'integer','minimum':1,'maximum':5000}}
    models['CareerFormSchema']=object_schema({'schemaVersion':{'type':'integer','minimum':1},'fields':{'type':'array','maxItems':30,'items':REF('CareerFormField')}})
    models['CareerFormField']={'oneOf':[object_schema(base_field),object_schema({**base_field,'options':{'type':'array','minItems':1,'maxItems':100,'uniqueItems':True,'items':{'type':'string','maxLength':100}}})]}
    models['CareerOpportunityInput']=object_schema({'title':{'type':'string','minLength':1,'maxLength':180},'slug':{'type':'string','pattern':'^[a-z0-9]+(?:-[a-z0-9]+)*$','maxLength':200},'kind':{'enum':['JOB','INTERNSHIP','INFLUENCER','AFFILIATE']},'description':{'type':'string','minLength':1,'maxLength':20000},'fieldsSchema':REF('CareerFormSchema'),'closesAt':{'type':['string','null'],'format':'date-time'},'state':{'enum':['DRAFT','PUBLISHED','CLOSED']}})
    models['CareerOpportunityInput']['required'].remove('closesAt')
    models['CareerOpportunity']=object_schema({'id':UUID,'title':{'type':'string','maxLength':180},'slug':{'type':'string','maxLength':200},'kind':{'enum':['JOB','INTERNSHIP','INFLUENCER','AFFILIATE']},'description':{'type':'string'},'fieldsSchema':REF('CareerFormSchema'),'closesAt':{'type':['string','null'],'format':'date-time'},'state':{'enum':['DRAFT','PUBLISHED','CLOSED']},'version':VERSION})
    models['CareerSubmission']=object_schema({'name':{'type':'string','minLength':1,'maxLength':160},'email':{'type':'string','format':'email','maxLength':254},'answers':{'type':'object','maxProperties':30,'additionalProperties':True},'cvFileId':{'anyOf':[UUID,{'type':'null'}]},'privacyPolicyVersion':{'type':'string','maxLength':80},'antiSpamToken':{'type':'string','minLength':1,'maxLength':4096}})
    models['CareerSubmission']['required'].remove('cvFileId')
    models['CareerCreated']=object_schema({'id':UUID,'state':{'const':'SUBMITTED'}})
    models['CareerSummary']=object_schema({'id':UUID,'opportunityId':UUID,'name':{'type':'string','maxLength':160},'state':{'enum':['SUBMITTED','REVIEWED','SHORTLISTED','REJECTED','CLOSED']},'createdAt':{'type':'string','format':'date-time'}})
    models['CareerApplication']=object_schema({'id':UUID,'opportunityId':UUID,'name':{'type':'string','maxLength':160},'email':{'type':'string','format':'email','maxLength':254},'answers':{'type':'object','additionalProperties':True},'cvFileId':{'anyOf':[UUID,{'type':'null'}]},'state':{'enum':['SUBMITTED','REVIEWED','SHORTLISTED','REJECTED','CLOSED']},'version':VERSION})
    models['CareerTransition']=object_schema({'state':{'enum':['REVIEWED','SHORTLISTED','REJECTED','CLOSED']},'reason':{'type':'string','minLength':1,'maxLength':500}})
    models['CareerChanged']=object_schema({'id':UUID,'state':{'enum':['REVIEWED','SHORTLISTED','REJECTED','CLOSED']},'version':VERSION})
    models['CareerSheetContext']=object_schema({'applicationId':UUID,'opportunityTitle':{'type':'string','maxLength':180},'name':{'type':'string','maxLength':160},'email':{'type':'string','format':'email','maxLength':254},'submittedAt':{'type':'string','format':'date-time'},'state':{'enum':['SUBMITTED','REVIEWED','SHORTLISTED','REJECTED','CLOSED']},'approvedAnswers':{'type':'object','additionalProperties':True}})
    models['CareerUploadSessionInput']=object_schema({'antiSpamToken':{'type':'string','minLength':1,'maxLength':4096}})
    models['CareerUploadSession']=object_schema({'uploadToken':{'type':'string','minLength':43,'maxLength':43,'pattern':'^[A-Za-z0-9_-]{43}$'},'expiresAt':{'type':'string','format':'date-time'},'maximumBytes':{'type':'integer','minimum':1,'maximum':5242880}})
    models['CareerOpportunityPage']=object_schema({'items':{'type':'array','items':REF('CareerOpportunity')},'page':{'type':'integer','minimum':0},'size':{'type':'integer','minimum':1,'maximum':100},'total':{'type':'integer','minimum':0}})
    models['CareerSummaryPage']=object_schema({'items':{'type':'array','items':REF('CareerSummary')},'page':{'type':'integer','minimum':0},'size':{'type':'integer','minimum':1,'maximum':100},'total':{'type':'integer','minimum':0}})
    def op(api,desc,response,params=(),scope=None,body=None,status=200):
        value=operation(api,desc,response,list(params))
        if scope:
            value['security']=[{'workload':[scope],'signedActor':[]}]
        if body:
            value['requestBody']={'required':True,'content':{'application/json':{'schema':REF(body)}}}
        if status!=200:
            value['responses'][str(status)]=value['responses'].pop('200')
        value['responses'][str(status)].setdefault('headers',{})['Cache-Control']={'schema':{'const':'no-store'}}
        return value
    paths['/api/v1/career-opportunities']={'get':op('API-103','Public, anti-abuse limited, published and open opportunities only. Bounded pagination.','CareerOpportunityPage',[parameter('kind','query',{'enum':['JOB','INTERNSHIP','INFLUENCER','AFFILIATE']}),parameter('page','query',{'type':'integer','minimum':0}),parameter('size','query',{'type':'integer','minimum':1,'maximum':100}),parameter('sort','query',{'enum':['createdAt,asc','createdAt,desc','title,asc','title,desc']})])}
    paths['/api/v1/staff/career-opportunities']={'post':op('API-104','Exact Commerce signed SALES actor with careers.write. Closed form schema; publication is a staff-authorized action. Idempotency-Key required.','CareerOpportunity',[parameter('Idempotency-Key','header',{'type':'string','minLength':1,'maxLength':100},True)],'careers.write_WITH_SIGNED_ACTOR','CareerOpportunityInput',201)}
    paths['/api/v1/career-opportunities/{id}/applications']={'post':op('API-105','Public, anti-abuse verified submission. Requires configured privacy policy, retention, recipient group and encryption keys. Answers are checked against captured form revision; an optional private CLEAN CV is claimed once only when X-Career-Upload-Token matches its upload session capability. Applicant email encrypted; outbox payload excludes applicant data.','CareerCreated',[parameter('id','path',UUID,True),parameter('Idempotency-Key','header',{'type':'string','minLength':1,'maxLength':100},True),parameter('X-Career-Upload-Token','header',{'type':'string','minLength':1,'maxLength':512})],body='CareerSubmission',status=201)}
    upload=op('API-157','Public anti-abuse verified CAREER_CV upload capability. Requires the same approved career privacy, retention, recipient, encryption-key and anti-spam configuration as application intake. The 256-bit token is stored as SHA-256 in upload_session and encrypted in the owner idempotency response for safe replay; it expires after 30 minutes and is not a download credential. Anonymous distributor proof purposes are never issued.','CareerUploadSession',[parameter('Idempotency-Key','header',{'type':'string','minLength':1,'maxLength':100},True)],body='CareerUploadSessionInput',status=201)
    paths['/api/v1/career-upload-sessions']={'post':upload}
    paths['/api/v1/staff/career-applications']={'get':op('API-106','Exact Commerce signed SALES actor with careers.read. Summaries only; no email, answers or CV.','CareerSummaryPage',[parameter('opportunityId','query',UUID),parameter('state','query',{'enum':['SUBMITTED','REVIEWED','SHORTLISTED','REJECTED','CLOSED']}),parameter('page','query',{'type':'integer','minimum':0}),parameter('size','query',{'type':'integer','minimum':1,'maximum':100}),parameter('sort','query',{'enum':['createdAt,asc','createdAt,desc','name,asc','name,desc']})],'careers.read_WITH_SIGNED_ACTOR')}
    appid=parameter('id','path',UUID,True)
    paths['/api/v1/staff/career-applications/{id}']={'get':op('API-156','Exact Commerce signed SALES actor with careers.read. Audited confidential access; CV download uses separate protected-file API.','CareerApplication',[appid],'careers.read_WITH_SIGNED_ACTOR')}
    paths['/api/v1/staff/career-applications/{id}']['patch']=op('API-107','Exact Commerce signed SALES actor with careers.manage. State machine and If-Match enforced; stable idempotency key and audit required.','CareerChanged',[appid,parameter('If-Match','header',{'type':'string','pattern':'^"(0|[1-9][0-9]{0,18})"$'},True),parameter('Idempotency-Key','header',{'type':'string','minLength':1,'maxLength':100},True)],'careers.manage_WITH_SIGNED_ACTOR','CareerTransition')
    paths['/internal/v1/career-applications/{id}/sheet-context']={'get':op('API-128','Exact Integration workload only. Audited minimum approved field allowlist; never returns CV or file bytes.','CareerSheetContext',[parameter('id','path',UUID,True)],'sheets.read')}
    spec['components']['securitySchemes']['signedActor']={'type':'apiKey','in':'header','name':'X-Nigson-Actor'}
    spec['components']['securitySchemes']['workload']['flows']['clientCredentials']['scopes'].update({s:'Exact signed Commerce BFF staff career permission' for s in ['careers.write_WITH_SIGNED_ACTOR','careers.read_WITH_SIGNED_ACTOR','careers.manage_WITH_SIGNED_ACTOR']})
    return spec
